package com.intermarche.backoffice.engine.stock;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class StockEligibilityTest {
 @Test void useByIsInclusiveButMinimumClientLifeAdvancesTheCutoff(){var date=LocalDate.of(2026,10,30);assertTrue(StockEligibility.dateAllowed(date.atTime(23,59),date,null,0,false));assertFalse(StockEligibility.dateAllowed(date.plusDays(1).atStartOfDay(),date,null,0,false));assertTrue(StockEligibility.dateAllowed(date.minusDays(2).atTime(23,59),date,null,2,false));assertFalse(StockEligibility.dateAllowed(date.minusDays(1).atStartOfDay(),date,null,2,false));}
 @Test void bestBeforeIsAdvisoryUnlessPolicyMakesItStrict(){var date=LocalDate.of(2026,10,20);assertTrue(StockEligibility.dateAllowed(date.plusDays(2).atStartOfDay(),null,date,0,false));assertFalse(StockEligibility.dateAllowed(date.plusDays(2).atStartOfDay(),null,date,0,true));assertFalse(StockEligibility.qualityAllowed("QUARANTINE"));assertFalse(StockEligibility.qualityAllowed("BLOCKED"));}
 @Test void fefoAndFifoCanChooseDifferentPhysicalLots(){var now=LocalDateTime.of(2026,10,28,10,0);var earlyEntry=new StockEligibility.Candidate(1L,now.minusDays(10),now.toLocalDate().plusDays(20),null);var earlyExpiry=new StockEligibility.Candidate(2L,now.minusDays(1),now.toLocalDate().plusDays(2),null);var rows=new ArrayList<>(List.of(earlyEntry,earlyExpiry));rows.sort(StockEligibility.comparator("FEFO"));assertEquals(2L,rows.getFirst().id());rows.sort(StockEligibility.comparator("FIFO"));assertEquals(1L,rows.getFirst().id());}
}
